struct Fuzz {
func useCopyVar(copy: inout String) {
    let s /*
*/= copy
    _ = s

    // We can copy from a variable named `copy`
    let t = copy copy
    copy = t

    // We can do member access and subscript a variable named `copy`
    let i = copy.startIndex
    let _ = copy[i]
}
}
